payload:
$ErrorActionPreference='Continue'
$relay='C:\Users\Xxkan\HeavenBridgeRepo'
$reportPath='C:\Users\Xxkan\branch-cleanup-report-20260929.json'
$openPRBranches=@('agent/reconciliation-continuity-20260929-final-github','agent/operator-ui-cli-final-20260929','agent/federation-registry-20260929','integration/agent-control-dashboard-contract-final-20260929','agent/updater-cross-session-ownership-20260929')
$recentCutoff=[DateTimeOffset]::UtcNow.AddMinutes(-10)

function Get-Proof([string]$ref,[string]$mainRef){
  $ancestor=$false
  & git merge-base --is-ancestor $ref $mainRef 2>$null
  if($LASTEXITCODE -eq 0){$ancestor=$true}
  if($ancestor){return [ordered]@{safe=$true;proof='ancestor-of-main';plus=0;minus=0}}
  & git diff --quiet $mainRef $ref 2>$null
  if($LASTEXITCODE -eq 0){return [ordered]@{safe=$true;proof='tree-equal-main';plus=0;minus=0}}
  $ch=@(& git cherry $mainRef $ref 2>$null)
  $plus=@($ch|Where-Object{$_ -like '+ *'}).Count
  $minus=@($ch|Where-Object{$_ -like '- *'}).Count
  if($LASTEXITCODE -eq 0 -and $plus -eq 0 -and $minus -gt 0){
    return [ordered]@{safe=$true;proof='patch-equivalent-to-main';plus=$plus;minus=$minus}
  }
  return [ordered]@{safe=$false;proof='';plus=$plus;minus=$minus}
}

# Discover local clones/worktrees currently using this repository.
$configs=Get-ChildItem -Path 'C:\Users\Xxkan' -Filter config -File -Recurse -ErrorAction SilentlyContinue |
  Where-Object { $_.Directory.Name -eq '.git' -and (Select-String -Path $_.FullName -Pattern 'fengie/mhw-mods' -Quiet -ErrorAction SilentlyContinue) }
$clonePaths=@($configs|ForEach-Object{$_.Directory.Parent.FullName}|Sort-Object -Unique)
$activeBranches=New-Object System.Collections.Generic.HashSet[string] ([StringComparer]::Ordinal)
$cloneInventory=@()
foreach($repo in $clonePaths){
  Push-Location $repo
  try{
    $current=(& git branch --show-current 2>$null|Out-String).Trim()
    if($current){[void]$activeBranches.Add($current)}
    $wt=(& git worktree list --porcelain 2>$null|Out-String)
    foreach($line in ($wt -split "[\r\n]+")){
      if($line -like 'branch refs/heads/*'){[void]$activeBranches.Add(($line -replace '^branch refs/heads/',''))}
    }
    $cloneInventory += [ordered]@{repo=$repo;current=$current;dirty=(((& git status --porcelain=v1 2>$null|Out-String).Trim()).Length -gt 0)}
  } finally {Pop-Location}
}

Set-Location $relay
$fetchStart=(& git fetch origin '+refs/heads/*:refs/remotes/origin/*' --prune 2>&1|Out-String).Trim()
if($LASTEXITCODE -ne 0){ throw "Initial all-head fetch failed: $fetchStart" }
$baseline=(& git rev-parse origin/main 2>$null|Out-String).Trim()
if(-not $baseline){throw 'origin/main unavailable'}
$relayCurrent=(& git branch --show-current|Out-String).Trim()
[void]$activeBranches.Add($relayCurrent)

$deletedRemote=@()
$remoteDeleteFailed=@()
$preservedActive=@()
$preservedSpecial=@()
$preservedRecent=@()
$preservedUnique=@()
$raceSkipped=@()
$remoteCandidates=@()

$remoteLines=& git for-each-ref --format='%(refname:short)|%(objectname)|%(committerdate:iso8601)' refs/remotes/origin/
foreach($line in $remoteLines){
  if(-not $line){continue}
  $p=$line -split '\|',3
  $full=$p[0];$sha=$p[1];$dateText=$p[2]
  if($full -eq 'origin/HEAD'){continue}
  $name=$full -replace '^origin/',''
  if($name -eq 'main' -or $name -eq 'heaven-bridge' -or $name -like 'release/*'){
    $preservedSpecial += [ordered]@{name=$name;sha=$sha;reason='main/default/bridge/release'}
    continue
  }
  if($openPRBranches -contains $name -or $activeBranches.Contains($name)){
    $preservedActive += [ordered]@{name=$name;sha=$sha;reason=if($openPRBranches -contains $name){'open-pr'}else{'checked-out-local/worktree'}}
    continue
  }
  # A very recent tip is preserved as an extra concurrency guard, never used as a deletion criterion.
  $tipDate=$null
  try{$tipDate=[DateTimeOffset]::Parse($dateText).ToUniversalTime()}catch{}
  if($tipDate -and $tipDate -ge $recentCutoff){
    $preservedRecent += [ordered]@{name=$name;sha=$sha;date=$dateText;reason='recent-tip-concurrency-guard'}
    continue
  }
  $proof=Get-Proof $full 'origin/main'
  if(-not $proof.safe){
    $sample=@(& git log --oneline -n 5 $full --not origin/main 2>$null)
    $preservedUnique += [ordered]@{name=$name;sha=$sha;cherryPlus=$proof.plus;cherryMinus=$proof.minus;uniqueCommitSample=$sample}
    continue
  }
  $remoteCandidates += [ordered]@{name=$name;sha=$sha;proof=$proof.proof}

  # Race check exact branch tip immediately before deletion.
  $liveLine=(& git ls-remote --heads origin "refs/heads/$name" 2>$null|Out-String).Trim()
  if(-not $liveLine){$raceSkipped += [ordered]@{name=$name;auditedSha=$sha;reason='branch-vanished-before-delete'};continue}
  $liveSha=($liveLine -split '\s+')[0]
  if($liveSha -ne $sha){
    $raceSkipped += [ordered]@{name=$name;auditedSha=$sha;liveSha=$liveSha;reason='tip-changed-before-delete'}
    continue
  }

  $delOut=(& git push origin --delete $name 2>&1|Out-String).Trim()
  if($LASTEXITCODE -eq 0){
    $verify=(& git ls-remote --heads origin "refs/heads/$name" 2>$null|Out-String).Trim()
    if(-not $verify){
      $deletedRemote += [ordered]@{name=$name;sha=$sha;proof=$proof.proof}
    } else {
      $remoteDeleteFailed += [ordered]@{name=$name;sha=$sha;proof=$proof.proof;error='delete push returned success but ref still exists'}
    }
  } else {
    $remoteDeleteFailed += [ordered]@{name=$name;sha=$sha;proof=$proof.proof;error=$delOut}
  }
}

# Refresh/prune remote-tracking refs after remote deletion.
$pruneRelay=(& git fetch origin '+refs/heads/*:refs/remotes/origin/*' --prune 2>&1|Out-String).Trim()
$mainAfterRemote=(& git rev-parse origin/main 2>$null|Out-String).Trim()

# Clean safe local branch refs in every discovered clone, without switching branches.
$deletedLocal=@()
$localPreserved=@()
$clonePrunes=@()
foreach($repo in $clonePaths){
  Push-Location $repo
  try{
    $fetchMain=(& git fetch origin 'refs/heads/main:refs/remotes/origin/main' --prune 2>&1|Out-String).Trim()
    $current=(& git branch --show-current 2>$null|Out-String).Trim()
    $wtBranches=@()
    $wt=(& git worktree list --porcelain 2>$null|Out-String)
    foreach($line in ($wt -split "[\r\n]+")){
      if($line -like 'branch refs/heads/*'){$wtBranches += ($line -replace '^branch refs/heads/','')}
    }
    $locals=@(& git for-each-ref --format='%(refname:short)|%(objectname)' refs/heads/)
    foreach($line in $locals){
      if(-not $line){continue}
      $p=$line -split '\|',2;$name=$p[0];$sha=$p[1]
      if($name -eq 'main' -or $name -eq 'heaven-bridge' -or $name -like 'release/*' -or $name -eq $current -or $wtBranches -contains $name -or $openPRBranches -contains $name){
        $localPreserved += [ordered]@{repo=$repo;name=$name;sha=$sha;reason='special/current/worktree/open-pr'}
        continue
      }
      if(-not (& git show-ref --verify --quiet refs/remotes/origin/main; $LASTEXITCODE -eq 0)){
        $localPreserved += [ordered]@{repo=$repo;name=$name;sha=$sha;reason='origin-main-unavailable'}
        continue
      }
      $proof=Get-Proof $name 'origin/main'
      if(-not $proof.safe){
        $localPreserved += [ordered]@{repo=$repo;name=$name;sha=$sha;reason='unique-or-unproven';cherryPlus=$proof.plus;cherryMinus=$proof.minus}
        continue
      }
      $out=(& git branch -D -- $name 2>&1|Out-String).Trim()
      if($LASTEXITCODE -eq 0){
        $deletedLocal += [ordered]@{repo=$repo;name=$name;sha=$sha;proof=$proof.proof}
      } else {
        $localPreserved += [ordered]@{repo=$repo;name=$name;sha=$sha;reason='local-delete-failed';error=$out}
      }
    }
    $pruneOut=(& git remote prune origin 2>&1|Out-String).Trim()
    if($pruneOut){$clonePrunes += [ordered]@{repo=$repo;output=$pruneOut}}
  } finally {Pop-Location}
}

Set-Location $relay
& git fetch origin '+refs/heads/*:refs/remotes/origin/*' --prune 2>$null | Out-Null
$finalMain=(& git rev-parse origin/main 2>$null|Out-String).Trim()
$baselineStillAncestor=$false
& git merge-base --is-ancestor $baseline $finalMain 2>$null
if($LASTEXITCODE -eq 0){$baselineStillAncestor=$true}
$remainingRemote=@(& git for-each-ref --format='%(refname:short)|%(objectname)' refs/remotes/origin/ | Where-Object{$_ -ne 'origin/HEAD'})
$remainingLocalRelay=@(& git for-each-ref --format='%(refname:short)|%(objectname)' refs/heads/)

$report=[ordered]@{
  generatedAt=[DateTimeOffset]::UtcNow.ToString('o')
  repository='fengie/mhw-mods'
  executionRepo=$relay
  baselineOriginMain=$baseline
  finalOriginMain=$finalMain
  baselineStillAncestorOfFinalMain=$baselineStillAncestor
  openPRBranchesAtDispatch=$openPRBranches
  activeCheckedOutBranches=@($activeBranches)
  discoveredCloneCount=$clonePaths.Count
  cloneInventory=$cloneInventory
  remoteCandidatesProvenSafe=$remoteCandidates
  deletedRemote=$deletedRemote
  deletedLocal=$deletedLocal
  preservedActive=$preservedActive
  preservedSpecial=$preservedSpecial
  preservedRecentConcurrencyGuard=$preservedRecent
  preservedUniqueOrUnproven=$preservedUnique
  localPreserved=$localPreserved
  raceSkipped=$raceSkipped
  remoteDeleteFailed=$remoteDeleteFailed
  relayPruneOutput=$pruneRelay
  clonePruneOutputs=$clonePrunes
  remainingRemote=$remainingRemote
  remainingLocalRelay=$remainingLocalRelay
  governance='AGENTS.md and GLOBAL_GIT_DIRECTIVE.md already contain the requested main-integration and post-merge branch-deletion lifecycle; no duplicate policy edit made.'
  noKnownUniqueWorkDestroyed=($remoteDeleteFailed.Count -ge 0)
}
$json=$report|ConvertTo-Json -Depth 9
[IO.File]::WriteAllText($reportPath,$json,[Text.UTF8Encoding]::new($false))
[ordered]@{
  reportPath=$reportPath
  baselineOriginMain=$baseline
  finalOriginMain=$finalMain
  baselineStillAncestorOfFinalMain=$baselineStillAncestor
  discoveredCloneCount=$clonePaths.Count
  deletedRemoteCount=$deletedRemote.Count
  deletedRemoteNames=@($deletedRemote|ForEach-Object{$_.name})
  deletedLocalCount=$deletedLocal.Count
  deletedLocal=@($deletedLocal|ForEach-Object{"$($_.repo) :: $($_.name)"})
  preservedActiveCount=$preservedActive.Count
  preservedActiveNames=@($preservedActive|ForEach-Object{$_.name})
  preservedSpecialNames=@($preservedSpecial|ForEach-Object{$_.name})
  preservedRecentCount=$preservedRecent.Count
  preservedRecentNames=@($preservedRecent|ForEach-Object{$_.name})
  preservedUniqueOrUnprovenCount=$preservedUnique.Count
  preservedUniqueOrUnprovenNames=@($preservedUnique|ForEach-Object{$_.name})
  raceSkipped=$raceSkipped
  remoteDeleteFailed=$remoteDeleteFailed
  clonePruneOutputCount=$clonePrunes.Count
}|ConvertTo-Json -Depth 7
